var research = @"D:\RotateRings\Research\physics_v3";
var pack = JsonUtility.FromJson<RotateRingsLevelPack>(System.IO.File.ReadAllText(System.IO.Path.Combine(research, "full500\\source_parity_pack.json")));
var catalog = JsonUtility.FromJson<RotateRingsTemplateCatalog>(System.IO.File.ReadAllText(System.IO.Path.Combine(research, "full500\\source_templates.json")));
var level = pack.levels.Find(item => item.id == 10010);
var host = new GameObject("source10010 ring3 removal diagnostic") { hideFlags = HideFlags.HideAndDontSave };
var lines = new System.Collections.Generic.List<string>();
try {
    var world = host.AddComponent<RotateRingsCollisionWorld>(); world.Build(level, catalog);
    var angles = new System.Collections.Generic.Dictionary<int,float>();
    foreach (var part in level.parts) angles[part.id] = part.angle;
    var removed = new System.Collections.Generic.HashSet<int> { 6, 7, 8 };
    var slides = new System.Collections.Generic.Dictionary<int,float>();
    world.ApplyState(angles, removed, slides);
    var initial = (RotateRingsCollisionWorld.BindingStateSnapshot)world.CaptureBindingState();
    lines.Add("source=10010;removed=6,7,8;ring3Angle=" + world.GetAngle(3).ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";active=" + string.Join(",", initial.activeRingRelationIndices ?? new int[0]) + ";passive=" + string.Join(",", initial.passiveRingRelationIndices ?? new int[0]) + ";bindings=" + world.ActiveAuthoredContactCount + ";contacts=" + world.GetActiveContactSummary());
    System.Action<string,float> attempt = (label, delta) => {
        world.ApplyState(angles, removed, slides);
        world.BeginGesture(3);
        float start = world.GetAngle(3); bool blocked;
        float reached = world.ClampRotation(3, start, delta, out blocked);
        int blocker = world.LastBlockerOwner; string blockerRole = world.LastBlockerRole;
        bool hardOverlap = world.HasHardOverlap(3); int hardOwner = world.LastBlockerOwner; string hardRole = world.LastBlockerRole;
        world.EndGesture(3, blocked ? Mathf.Sign(delta) : 0f);
        var snap = (RotateRingsCollisionWorld.BindingStateSnapshot)world.CaptureBindingState();
        lines.Add(label + ";requested=" + delta.ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";reached=" + (reached-start).ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";settled=" + world.GetAngle(3).ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";blocked=" + blocked + ";blocker=" + blocker + ":" + blockerRole + ";hardOverlap=" + hardOverlap + ";hardBlocker=" + hardOwner + ":" + hardRole + ";canSolve=" + world.CanSolve(3) + ";bindings=" + world.ActiveAuthoredContactCount + ";active=" + string.Join(",", snap.activeRingRelationIndices ?? new int[0]) + ";passive=" + string.Join(",", snap.passiveRingRelationIndices ?? new int[0]) + ";contacts=" + world.GetActiveContactSummary());
    };
    foreach (float delta in new[] { 120f, -120f, 180f, -180f }) attempt("ring3-turn", delta);
    world.ApplyState(angles, removed, slides);
    foreach (var contact in world.GetActiveAuthoredContacts()) {
        if (contact.kind != "ring-link" || contact.targetId != 3 || contact.ownerRole != "head_trigger" || contact.targetRole != "body") continue;
        if (!world.TryGetShapeWorldCenter(contact.ownerId, contact.ownerShapeIndex, out var sourceCenter)) continue;
        Vector2 sourceVector = sourceCenter - (Vector2)world.OwnerTransform(3).position;
        if (sourceVector.sqrMagnitude < 1e-8f) continue;
        float bearing = Mathf.Atan2(sourceVector.y, sourceVector.x) * Mathf.Rad2Deg;
        var receiverTemplate = System.Array.Find(catalog.templates, template => template.id == level.parts.Find(part => part.id == 3).templateId);
        float desired = Mathf.DeltaAngle(world.GetAngle(3) + receiverTemplate.gapDirectionDeg, bearing);
        float gap = receiverTemplate.visualGap > .5f ? receiverTemplate.visualGap : Mathf.Max(0f, level.parts.Find(part => part.id == 3).gap);
        float half = gap * .5f;
        foreach (float margin in new[] { 0f, -half, half, -(half + 8f), half + 8f }) attempt("ring3-guided-from-" + contact.ownerId + "-bearing-" + bearing.ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + "-margin-" + margin.ToString("F1", System.Globalization.CultureInfo.InvariantCulture), desired + margin);
    }
    var destination = System.IO.Path.Combine(research, "source10010_ring3_after_bottom_diagnostic.txt");
    System.IO.File.WriteAllLines(destination, lines);
    return destination + " rows=" + lines.Count;
}
finally { UnityEngine.Object.DestroyImmediate(host); }
